export function seededRandom(seed){let a=seed>>>0;return()=>{a+=0x6D2B79F5;let t=a;t=Math.imul(t^t>>>15,t|1);t^=t+Math.imul(t^t>>>7,t|61);return((t^t>>>14)>>>0)/4294967296;};}
export class BastionState {
 constructor(config){this.config=config;this.reset();}
 reset(seed=this.config.seed){this.seed=Number(seed)>>>0;this.random=seededRandom(this.seed);this.cycle=0;this.phase='reset';this.elapsed=0;this.totalTime=0;this.events=[];this.coreIndex=0;this.gapBonus=false;this.barrageDuration=this.config.timings.barrage;this.patterns=[];this.markedRoute=null;this.currentRoute=null;this.routeSeconds=Object.fromEntries(this.config.routes.ids.map(id=>[id,0]));this.launchers=this.config.launchers.positions.map((_,i)=>({id:'launcher-'+i,health:this.config.launchers.health,destroyed:false}));this.grazeBonus=0;this.grazes=0;this.strikeKey=null;this.strikeMultiplier=1;this.pulseSequence=0;this.nextOverlap=0;this.overlapCount=0;this.damageTaken=0;this.hitsTaken=0;}
 get baseBarrageDuration(){return this.patterns.includes('gatling')?(this.config.gatling.barrageSeconds??this.config.timings.barrage):this.config.timings.barrage;}
 get exposed(){return this.phase==='barrage';}
 get duration(){return this.phase==='reset'?this.config.timings.reset:this.phase==='windup'?this.config.timings.windup:this.phase==='pulse'?this.config.timings.pulse:this.phase==='barrage'?this.barrageDuration:Infinity;}
 markRoute(){const entries=Object.entries(this.routeSeconds),total=entries.reduce((n,[,v])=>n+v,0);entries.sort((a,b)=>b[1]-a[1]);this.markedRoute=total>=this.config.routes.minimumSeconds&&entries[0][1]/Math.max(total,.001)>=this.config.routes.dominance?entries[0][0]:null;this.routeSeconds=Object.fromEntries(this.config.routes.ids.map(id=>[id,0]));}
 choosePatterns(){const sequence=this.config.barrage.attackSequence||this.config.barrage.pool;this.patterns=[sequence[(this.cycle-1)%sequence.length]||'gatling'];}
 enter(phase){this.phase=phase;this.elapsed=0;this.events.push({type:phase,cycle:this.cycle});if(phase==='windup'){this.cycle++;this.coreIndex=(this.seed+this.cycle-1)%this.config.core.locations.length;this.gapBonus=false;this.markRoute();this.choosePatterns();}if(phase==='pulse')this.events.push({type:'wave',id:++this.pulseSequence});if(phase==='barrage'){this.barrageDuration=this.baseBarrageDuration*(this.gapBonus?1+this.config.timings.gapExtension:1);this.nextOverlap=this.config.escalation.overlapDelay;this.overlapCount=0;this.grazeBonus=0;this.strikeKey=null;}}
 step(dt){this.events=[];if(this.phase==='defeated')return this.events;dt=Math.max(0,dt);this.totalTime+=dt;this.elapsed+=dt;if(this.phase==='barrage'&&this.cycle>=this.config.escalation.overlapFromCycle){while(this.elapsed>=this.nextOverlap&&this.overlapCount<this.config.escalation.overlapPulses){this.events.push({type:'wave',id:++this.pulseSequence});this.nextOverlap+=this.config.escalation.overlapInterval;this.overlapCount++;}}if(this.elapsed>=this.duration){this.enter({reset:'windup',windup:'pulse',pulse:'barrage',barrage:'reset'}[this.phase]);}return this.events;}
 trackRoute(id,dt){this.currentRoute=id;if(id&&id in this.routeSeconds)this.routeSeconds[id]+=dt;}
 awardGap(){if(this.gapBonus)return false;this.gapBonus=true;if(this.exposed)this.barrageDuration+=this.baseBarrageDuration*this.config.timings.gapExtension;return true;}
 graze(orb){if(!this.exposed||orb.grazed)return false;orb.grazed=true;this.grazes++;this.grazeBonus=Math.min(this.config.projectiles.grazeCap,this.grazeBonus+this.config.projectiles.grazePerOrb);return true;}
 multiplier(key){if(this.strikeKey!==key){this.strikeKey=key;this.strikeMultiplier=1+this.grazeBonus;this.grazeBonus=0;}return this.strikeMultiplier;}
 hurtLauncher(index,power){const l=this.launchers[index];if(!l||l.destroyed||this.exposed||this.phase==='defeated')return 0;const dealt=Math.min(l.health,Math.max(0,power));l.health-=dealt;if(l.health<=0){l.destroyed=true;this.events.push({type:'launcher-destroyed',index});}return dealt;}
 defeat(){this.enter('defeated');this.grazeBonus=0;}
 diagnostics(){return{phase:this.phase,cycle:this.cycle,elapsed:this.elapsed,remaining:Math.max(0,this.duration-this.elapsed),seed:this.seed,patterns:[...this.patterns],coreIndex:this.coreIndex,coreLocation:this.config.core.locations[this.coreIndex].id,exposed:this.exposed,gapBonus:this.gapBonus,barrageDuration:this.barrageDuration,markedRoute:this.markedRoute,currentRoute:this.currentRoute,routeSeconds:{...this.routeSeconds},grazeBonus:this.grazeBonus,grazes:this.grazes,hitsTaken:this.hitsTaken,damageTaken:this.damageTaken,launchers:this.launchers.map(l=>({...l}))};}
}
